declare(strict_types=1);
if (!defined('ACADEMY_ROOT')) { http_response_code(403); exit; }

// This catalog is server-only. Answer keys are never serialized into an open test.
function academy_lab_catalog(): array
{
    $rows = [
        ['lab-navigation','both','01','Ο σωστός χώρος, ο σωστός ιδιοκτήτης',8,'Ξεχώρισε τις δύο εταιρείες και ξεκίνα χωρίς να αγγίξεις πραγματικά δεδομένα.'],
        ['lab-me-panels','melas','02','Από την κλήση στο lead πάνελ',18,'Μετέτρεψε τη συνομιλία σε πλήρη καταχώριση, με σωστή ποσότητα και τιμές.'],
        ['lab-me-pending','melas','03','Όταν τα στοιχεία δεν αρκούν',12,'Κράτησε μια ανεπιβεβαίωτη ευκαιρία σε εκκρεμότητα αντί να εφεύρεις στοιχεία.'],
        ['lab-me-service','melas','04','Συγκεκριμένη ανάγκη σε φωτοβολταϊκό πάρκο',14,'Κατάγραψε ανάγκη, υπεύθυνο, τοποθεσία και επόμενο βήμα.'],
        ['lab-me-review','melas','05','Έλεγχος, κατοχύρωση και αποκάλυψη',12,'Παίξε τον ρόλο του ελεγκτή χωρίς να αλλάξεις ιδιοκτήτη ή να παρακάμψεις την επαλήθευση.'],
        ['lab-me-payments','melas','06','Πληρωμένα πάνελ, σωστή προμήθεια',15,'Υπολόγισε τμηματικές αγορές και ξεχώρισε πληρωτέα από εξοφλημένα ποσά.'],
        ['lab-di-customer','distillogic','07','Μία εταιρεία, μία καθαρή καρτέλα',13,'Διάκρινε επωνυμία, διακριτικό τίτλο και στοιχεία επαφής χωρίς διπλοεγγραφές.'],
        ['lab-di-call','distillogic','08','Καταγραφή εμπορικής επικοινωνίας',12,'Αποτύπωσε ενδιαφέρον και πραγματικό στάδιο, όχι υποθετική επιτυχία.'],
        ['lab-di-followup','distillogic','09','Follow-up με ημερομηνία και συνέχεια',12,'Ενημέρωσε την υπάρχουσα επικοινωνία και συμφώνησε συγκεκριμένο επόμενο βήμα.'],
        ['lab-di-intake','distillogic','10','Discovery και παράδοση στην ομάδα',18,'Ξεχώρισε scope, εξαιρέσεις, προϋποθέσεις και τεχνικά άγνωστα.'],
        ['lab-di-proposal','distillogic','11','Πρόταση και ακριβές PDF έγκρισης',12,'Έλεγξε παραλήπτη, scope και νέα έγκριση μετά από αναθεώρηση.'],
        ['lab-privacy','both','12','Δικαιώματα και ασφαλής καθημερινή χρήση',10,'Χειρίσου οικονομικά, εξαγωγές και εταιρικά όρια με τον πραγματικό σου ρόλο.'],
        ['lab-me-final','melas','13','Τελική αποστολή · Melas Energiaki',25,'Ολοκλήρωσε μια υπόθεση πάνελ από την κλήση έως την πληρωτέα προμήθεια.'],
        ['lab-di-final','distillogic','14','Τελική αποστολή · Distillogic',25,'Οργάνωσε εταιρεία, επικοινωνία, follow-up και ασφαλή παράδοση πρότασης.'],
    ];
    $out=[];
    foreach ($rows as [$id,$company,$number,$title,$minutes,$goal]) {
        $out[$id]=compact('id','company','number','title','minutes','goal')+[
            'type'=>'lab','version'=>1,'quiz'=>[], 'requires'=>[],
        ];
    }
    $out['lab-me-final']['requires']=['lab-navigation','lab-me-panels','lab-me-pending','lab-me-service','lab-me-review','lab-me-payments','lab-privacy'];
    $out['lab-di-final']['requires']=['lab-navigation','lab-di-customer','lab-di-call','lab-di-followup','lab-di-intake','lab-di-proposal','lab-privacy'];
    $out['lab-me-review']['version']=2;
    $out['lab-me-payments']['version']=2;
    return $out;
}

function academy_lab_field(string $label, string $type, string $answer, string $why, array $options=[], bool $critical=false, string $group='Καταχώριση'): array
{
    return compact('label','type','answer','why','options','critical','group');
}

